# CONTRACT PROBE (owner's ruling R1b, 2026-09-01).
#
# F11 says "declared means invoked". This says "invoked means ACCEPTED".
#
# The baseline phase already executes the REAL vendored blocks with the
# payload the coder wrote, so the evidence was passing through this function
# and being thrown away: only the block id was recorded, never the answer. On
# one build six hours after #254 merged, every one of these came back here
# and none was seen:
#
#   analytics  {'error': 'metric and value required'}   <- envelope shape
#   team       'Unknown action: None'                   <- action in payload
#   workflow   'workflow unknown field(s): action'      <- action in payload
#   team       'Team access denied'                     <- precondition
#
# The build passed WRITER, passed its own gate, shipped a 216-file zip that
# booted -- and could not persist one record.
#
# Classified, never guessed: each class is decided by the block's literal
# answer plus the payload the coder actually passed.
def _default_action(block_id):
    """The action dispatch supplies when a handler passes none (the product's
    own rendered map), or None when the block has no default."""
    try:
        from app.block_inputs import default_block_action
        return default_block_action(block_id)
    except Exception:
        return None


def _classify_refusal(block_id, payload, action, answer):
    """Name the mismatch, or return None when the answer is not a refusal."""
    # A refusal is a TYPED answer: an error envelope whose kind is not
    # "unavailable" (a provider that is down is not the coder's contract).
    # Store blocks carry error_kind since Cerebrum-Blocks #137.
    if not isinstance(answer, dict):
        return None
    if answer.get("status") != "error" and answer.get("ok") is not False:
        return None
    if answer.get("error_kind") == "unavailable":
        return None
    text = str(answer.get("error") or "")
    data = payload if isinstance(payload, dict) else {}
    inner = data.get("input") if isinstance(data.get("input"), dict) else {}

    # (a) the action travelled inside the payload instead of as the keyword --
    # decided by the payload's structure, not by the words of the refusal.
    if "action" in data or "action" in inner:
        return (
            "%s: the action travelled inside the payload; app/dispatch.py "
            "routes payload keys into the block's record and reads the "
            "operation only from the action= keyword. Answered %r "
            "(CONTRACT: unknown action)" % (block_id, text[:90])
        )
    if action is None and _default_action(block_id) is None:
        return (
            "%s: called with no action= keyword. Answered %r "
            "(CONTRACT: unknown action)" % (block_id, text[:90])
        )

    # (b) the record is one level too deep for a block that reads it flat.
    # input_keys_read_by_block is harvested from source, not declared --
    # WORKAROUND, removal tracked in CerebrumDev.ai#256 (design:
    # Cerebrum-Blocks#90, block.json requires_inputs).
    if inner:
        try:
            import app.dispatch as _d
            reads = set(
                (_d.BLOCK_CONTRACTS.get(block_id) or {})
                .get("input_keys_read_by_block") or []
            )
        except Exception:
            reads = set()
        buried = sorted(k for k in inner if k in reads and k != "action")
        if buried and "input" not in reads:
            return (
                "%s: envelope shape -- %s sit inside 'input' but %s reads them "
                "at the top level. Answered %r (CONTRACT: envelope shape)"
                % (block_id, ", ".join(buried), block_id, text[:90])
            )

    # (c) an action that needs an id the block itself mints, called without it
    rule = RESOURCE_OBLIGATIONS.get(block_id) or {}
    if action and action in (rule.get("into") or []):
        carry = rule.get("carry")
        if carry and not data.get(carry) and not inner.get(carry):
            return (
                "%s: called %s without %s. %s mints it and must run first, "
                "with the returned %s carried in. Answered %r "
                "(CONTRACT: missing precondition)"
                % (block_id, action, carry, rule.get("ensure"), carry,
                   text[:90])
            )

    return (
        "%s: refused the payload the coder wrote -- answered %r (CONTRACT)"
        % (block_id, text[:110])
    )


def _recording_execute(block_id, *a, **kw):
    cap = _seen["cap"]
    if cap is not None:
        _seen["blocks"].setdefault(cap, set()).add(str(block_id))
    result = _real_execute(block_id, *a, **kw)
    if cap is not None:
        payload = a[0] if a else kw.get("payload")
        act = kw.get("action")
        if act is None and len(a) > 1:
            act = a[1]
        note = _classify_refusal(block_id, payload, act, result)
        if note:
            line = _miss(cap, "%s: %s" % (cap, note))

"""Block dispatch: the only door between a capability and a Store block.

``execute(block_id, payload, action=...)`` routes one call. The action travels
as a keyword -- never inside the payload dict -- so the block reads its
operation from the call, not from data a caller could forge.

A vendored block (``vendor/blocks/<id>``) wins when the checkout carries one;
otherwise the block implementation this platform ships in ``app/blocks`` is
used, and an unknown block id is a typed error rather than a silent success.
"""

from __future__ import annotations

import importlib
from typing import Any, Callable, Dict, List, Optional

from app.block_inputs import (
    ACTIONLESS_BLOCKS,
    BLOCK_DEFAULT_ACTIONS,
    BLOCK_INPUT_KEYS,
    attach_result,
    default_block_action,
    operation_param,
)

#: Each bound block's contract as this platform reads it: its default action
#: and the input keys it reads at the top level.
BLOCK_CONTRACTS: Dict[str, Dict[str, Any]] = {
    block_id: {
        "action": action,
        "input_keys_read_by_block": list(BLOCK_INPUT_KEYS.get(block_id, [])),
        "operation_key": ("operation" if block_id in ("payment_escrow", "transaction_state_machine") else "action"),
        "actionless": action is None,
    }
    for block_id, action in BLOCK_DEFAULT_ACTIONS.items()
}

REGISTRY_PREFIXES = ("vendor.blocks.", "vendor_blocks.")


def vendored(block_id: str) -> Optional[Callable[..., Dict[str, Any]]]:
    """The vendored Store block for an id, when the checkout carries one."""
    for prefix in REGISTRY_PREFIXES[:2]:
        try:
            module = importlib.import_module(prefix + str(block_id))
        except ImportError:
            continue
        except Exception:
            continue
        for name in ("run", "handle", "execute", "call"):
            candidate = getattr(module, name, None)
            if callable(candidate):
                return candidate
    return None


def _resolve(block_id: str) -> Optional[Callable[..., Dict[str, Any]]]:
    """The callable for a block id.

    This platform's own implementation of the id answers, and a vendored
    Store block is used only for an id the platform does not implement. The
    binding is by id and the door is this one function; the sealed Store
    blocks each carry their own domain contract (payment_id, entity_id, an
    HTTPS provider name) that this platform's records do not carry, so
    dispatching them our record would reach them as a refusal rather than as
    work. See README "Block binding".
    """
    from app import blocks

    ours = blocks.resolve(block_id)
    if ours is not None:
        return ours
    return vendored(block_id)


def known_blocks() -> List[str]:
    return sorted(BLOCK_CONTRACTS)


def execute(
    block_id: str,
    payload: Optional[Dict[str, Any]] = None,
    action: Optional[str] = None,
    params: Optional[Dict[str, Any]] = None,
    **kwargs: Any,
) -> Dict[str, Any]:
    """Run one block call and return its answer envelope.

    Two calling conventions, decided by the block's own contract: a vendored
    Store block is called ``run(input=<record>, action|operation=<operation>)``
    -- the operation under the keyword the block declares -- and this
    platform's own implementation is called with ``action=``/``payload=``. A
    block whose contract declares no action takes none.
    """
    block_id = str(block_id)
    data = dict(payload) if isinstance(payload, dict) else {}
    extra = dict(params or {})
    extra.update(kwargs)
    resolved_action = action if action is not None else default_block_action(block_id)
    actionless = resolved_action is None and (block_id in ACTIONLESS_BLOCKS or default_block_action(block_id) is None)
    if resolved_action is None and not actionless:
        return {
            "status": "error",
            "block": block_id,
            "action": None,
            "error": "Unknown action: None",
        }
    impl = _impl(block_id)
    if impl is None:
        found = vendored(block_id)
    else:
        found = None
    if found is not None:
        call_kwargs = operation_param(block_id, resolved_action)
        try:
            answer = found(input=data, **call_kwargs)
        except TypeError:
            # A vendored block that does not take ``input``: the platform's own
            # implementation of the same id answers instead.
            impl = _impl(block_id)
            if impl is None:
                return {
                    "status": "error",
                    "block": block_id,
                    "action": resolved_action,
                    "error": "block %s does not accept this platform's call" % block_id,
                }
            return _call_own(impl, block_id, data, resolved_action, actionless, extra)
        except Exception as exc:
            return {
                "status": "error",
                "block": block_id,
                "action": resolved_action,
                "error": "%s: %s" % (type(exc).__name__, exc),
            }
        if isinstance(answer, dict):
            answer.setdefault("block", block_id)
            answer.setdefault("action", resolved_action)
            return attach_result(answer, answer.get("result"))
        return {
            "status": "error",
            "block": block_id,
            "action": resolved_action,
            "error": "block %s answered no envelope" % block_id,
        }
    if impl is None:
        return {
            "status": "error",
            "block": block_id,
            "action": resolved_action,
            "error": "Unknown block: %s" % block_id,
        }
    return _call_own(impl, block_id, data, resolved_action, actionless, extra)


def _impl(block_id: str) -> Optional[Callable[..., Dict[str, Any]]]:
    from app import blocks

    return blocks.resolve(block_id)


def _call_own(
    impl: Callable[..., Dict[str, Any]],
    block_id: str,
    data: Dict[str, Any],
    resolved_action: Optional[str],
    actionless: bool,
    extra: Dict[str, Any],
) -> Dict[str, Any]:
    """Call this platform's implementation of a block id."""
    try:
        answer = impl(action=None if actionless else str(resolved_action), payload=data, **extra)
    except TypeError as exc:
        return {
            "status": "error",
            "block": block_id,
            "action": resolved_action,
            "error": "block %s refused its input: %s" % (block_id, exc),
        }
    except Exception as exc:  # a block that raises is a failed block
        return {
            "status": "error",
            "block": block_id,
            "action": resolved_action,
            "error": "%s: %s" % (type(exc).__name__, exc),
        }
    if not isinstance(answer, dict):
        return {
            "status": "error",
            "block": block_id,
            "action": resolved_action,
            "error": "block %s answered no envelope" % block_id,
        }
    answer.setdefault("block", block_id)
    answer.setdefault("action", resolved_action)
    return attach_result(answer, answer.get("result"))


def failed(answer: Any) -> bool:
    """True when a block answer is a refusal (the fail-closed test)."""
    if not isinstance(answer, dict):
        return True
    if answer.get("status") == "error":
        return True
    return answer.get("ok") is False


def refusal(block_id: str, answer: Dict[str, Any]) -> Dict[str, Any]:
    """A capability's own refusal, carrying the block's reason."""
    return {
        "ok": False,
        "error": "block %s refused: %s" % (block_id, str(answer.get("error") or "refused")),
        "block": block_id,
        "block_status": answer.get("status"),
    }
"""Block inputs: one place that knows what each bound Store block reads.

A capability never demands a block's own vocabulary from its caller. It
constructs the input the block declared it reads, from the domain record and
the runtime context, and passes the action as a keyword -- never inside the
payload dict.
"""

from __future__ import annotations

from typing import Any, Dict, List, Optional

#: Each bound block's own default action, read from its declared contract
#: (``block.json`` ``inputs[name=action|operation].default``). A block whose
#: contract declares no action takes none: ``None`` here, and the handler
#: passes no operation rather than inventing one.
BLOCK_DEFAULT_ACTIONS: Dict[str, Optional[str]] = {
    "analytics": "track_event",
    "approval_rules": "ingest",
    "audit": "log",
    "audit_chain": None,
    "auth": "validate",
    "billing": "record_usage",
    "capture": None,
    "dashboard": "render",
    "database": "query",
    "event_bus": "publish",
    "evidence_verifier": "store",
    "finance_canonical_model": None,
    "finance_data_quality": None,
    "finance_import": None,
    "finance_reconciliation": None,
    "finance_reconciliation_workflow": None,
    "governance_gate": "create_request",
    "ingestion_provenance": "build",
    "multi_tenant_rbac": None,
    "notification": "send",
    "ocr_v2": None,
    "payment_escrow": "hold",
    "review": "approve",
    "scim_provisioning": "register",
    "transaction_state_machine": "transition",
    "user_auth": None,
    "workflow": "run",
}

#: The keyword a block declares for its operation. Most Store blocks declare
#: ``action``; escrow and the state machine declare ``operation``.
BLOCK_OPERATION_KEYS: Dict[str, str] = {
    "payment_escrow": "operation",
    "transaction_state_machine": "operation",
}

#: Blocks that declare no action at all: the call carries no operation, and
#: the implementation answers its primary one.
ACTIONLESS_BLOCKS = frozenset(
    block_id for block_id, action in BLOCK_DEFAULT_ACTIONS.items() if action is None
) | {"audit_chain", "capture", "finance_data_quality", "finance_reconciliation", "ocr_v2"}


def operation_key(block_id: str) -> str:
    return BLOCK_OPERATION_KEYS.get(str(block_id), "action")


def operation_param(block_id: str, action: Optional[str]) -> Dict[str, Any]:
    """The operation as the block declares it -- the right keyword, or none.

    A block that declares no action takes none: passing an invented operation
    is what reaches a real block as 'Unknown action'.
    """
    if action is None:
        return {}
    return {operation_key(block_id): str(action)}


def declared_defaults(block_id: str) -> Optional[str]:
    """The default read from a vendored block.json beside the block, if any."""
    import json
    import os

    path = os.path.join(
        os.path.dirname(os.path.dirname(os.path.abspath(__file__))),
        "vendor", "blocks", str(block_id), "block.json",
    )
