                "token": ctx.get("scim_token"),
            },
            "principal_email": data.get("principal_email"),
            "role": data.get("role"),
            "permission": data.get("permission"),
            "result": data.get("result"),
        }
    elif block_id == "event_bus":
        prepared = {
            "topic": ctx.get("topic") or "platform.%s" % (ctx.get("capability") or "record"),
            "payload": {
                "capability": ctx.get("capability"),
