"""Offline fallback blocks for this platform's local dispatch runtime.

The Store's real blocks are vendored into vendor/blocks/<id>/ at build time
and are what app.dispatch loads first.  When a block a capability binds is
NOT vendored -- the local dispatch runtime is what the platform stands on
then -- these in-process shims answer the same envelope the vendored blocks
answer (``status`` success|error, ``ok``, ``block``, ``action``, ``result``),
so a capability's block call resolves offline instead of dying on an import
inside the box.  A shim that would otherwise reach the network never does:
the events stay in process.
"""

from __future__ import annotations

from typing import Any, Dict, Optional


class Shim:
    """The class app.blocks.BLOCK_REGISTRY hands to a peer block.

    The Store's workflow block executes each pipeline step by looking the
    child up in that registry and constructing it, then calling execute();
    each shim answers the same way so a prepared pipeline resolves offline.
    """

    BLOCK_ID = ""
    DEFAULT_ACTION: Optional[str] = None

    def execute(self, input_data: Any = None, params: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        data = input_data if isinstance(input_data, dict) else {"input": input_data}
        action = None
        if isinstance(params, dict):
            action = params.get("action") or params.get("operation")
        return self.handle(data, action=action, params=params or {})

    def handle(self, input_data: Any, action: Optional[str] = None,
               params: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        raise NotImplementedError

    #: called by the module-level run() the dispatch layer uses
    def run(self, **kwargs: Any) -> Dict[str, Any]:
        return self.execute(*_input_and_params(kwargs))


def ok(block_id: str, action: Optional[str], result: Any = None) -> Dict[str, Any]:
    return {
        "status": "success",
        "ok": True,
        "block": block_id,
        "action": action,
        "result": result if result is not None else {},
    }


def error(block_id: str, action: Optional[str], message: str) -> Dict[str, Any]:
    return {
        "status": "error",
        "ok": False,
        "block": block_id,
        "action": action,
        "error": str(message),
    }


def _input_and_params(kwargs: Dict[str, Any]) -> Any:
    """(input_data, params) from the kwargs dispatch hands a block.

    Exactly what the Store's own adapter does: the domain record travels in
    the declared ``input`` slot, the operation name arrives as a keyword
    (``action`` for most blocks, ``operation`` for the state machine), and
    every other keyword is a block parameter.  Reading the record from
    ``kwargs.get("input", kwargs)`` is what keeps a block that reads its
    fields flat and a block that reads them under ``input`` both working.
