"""Domain formulas for the Claims Platform.

The decisions this platform makes over its own records are arithmetic and
small state machines, and every number the customer owns -- the adjuster
approval limit, the payout stall window -- is a named setting read at the
point of use, never a literal typed into a capability handler. Country and
currency come from app.money_settings (deploy environment, else the locale
the customer declared in docs/declared_locale.json: GB / GBP).

Nothing here opens a database, calls a block or touches the network: these
are the formulas the handlers, the routes and the console all read.
"""

from __future__ import annotations

import os
from datetime import date, datetime, timezone
from typing import Any, Dict, List, Optional

from app import money_settings

#: The value above which a claim needs a seniors' approval as well as the
#: adjuster's. The insurer owns this number; the default is documented in
#: README.md and the operator overrides it in the deploy environment.
APPROVAL_LIMIT_ENV = "PLATFORM_ADJUSTER_APPROVAL_LIMIT"
APPROVAL_LIMIT_DEFAULT = 5000.0

#: How many days a scheduled payout may sit before it is flagged stalled.
STALL_DAYS_ENV = "PLATFORM_PAYOUT_STALL_DAYS"
STALL_DAYS_DEFAULT = 14.0

#: The pence precision every amount is carried at.
MONEY_PLACES = 2

#: The payout state machine: settlement_pending -> scheduled -> disbursed ->
#: reconciled. Transitions are declared here as data so the handler, the
#: console and the tests cannot disagree about them.
PAYOUT_TRANSITIONS: Dict[str, List[str]] = {
    "settlement_pending": ["scheduled"],
    "scheduled": ["disbursed"],
    "disbursed": ["reconciled"],
    "reconciled": [],
}
PAYOUT_TERMINAL_STATES = ["reconciled"]


def _number(value: Any, default: float = 0.0) -> float:
    try:
        if isinstance(value, bool) or value is None or value == "":
            return default
        return float(value)
    except (TypeError, ValueError):
        return default


def _setting(name: str, default: float) -> float:
    raw = (os.environ.get(name) or "").strip()
    if not raw:
        return default
    try:
        return float(raw)
    except ValueError:
        return default


def approval_limit() -> float:
    """The adjuster approval limit, as the operator set it."""
    value = _setting(APPROVAL_LIMIT_ENV, APPROVAL_LIMIT_DEFAULT)
    return value if value >= 0 else APPROVAL_LIMIT_DEFAULT


def stall_days() -> float:
    """Days a scheduled payout may sit before it is flagged stalled."""
    value = _setting(STALL_DAYS_ENV, STALL_DAYS_DEFAULT)
    return value if value >= 0 else STALL_DAYS_DEFAULT


def currency_label() -> str:
    """The ISO code the customer declared (GBP), read at the point of use."""
    return money_settings.currency()


def country_label() -> str:
    """The country the customer declared (GB), read at the point of use."""
    return money_settings.country()


def round_money(amount: Any) -> float:
    """An amount at the currency's precision, never at the caller's."""
    return round(_number(amount), MONEY_PLACES)


def money_label(amount: Any) -> str:
    """A display label for an amount, in the customer's own currency."""
    return "%s %.2f" % (currency_label(), round_money(amount))


def severity_band(amount: Any) -> str:
    """The severity band a repair cost falls in, relative to the approval
    limit the insurer set -- band boundaries are the operator's number, not
    a literal of this platform's."""
    value = _number(amount)
    limit = approval_limit()
    if limit <= 0:
        return "moderate"
    if value <= limit / 2:
        return "minor"
    if value <= limit:
        return "moderate"
    return "severe"

