    vendor/. A block-level refusal of this bare probe is still local
    execution; an import failure is the store dependency this test
    exists to catch."""
    for var in ("CEREBRUM_API_URL", "CEREBRUM_API_KEY", "CEREBRUM_API_TOKEN"):
        os.environ.pop(var, None)
    from app.dispatch import execute, load_block
    for block_id in ['approval_rules', 'audit', 'audit_chain', 'auth', 'capture', 'dashboard', 'database', 'evidence_chain', 'finance_reconciliation', 'image', 'insurance', 'insurance_v2', 'multi_tenant_rbac', 'notification', 'pdf', 'search', 'storage', 'task_listing', 'team', 'transaction_state_machine', 'user_auth', 'validation', 'web', 'workbench', 'workflow']:
