def _authored_by(text):
    import ast as _ast
    try:
        tree = _ast.parse(text or "")
    except (SyntaxError, ValueError):
        return ""
    for node in tree.body:
        if isinstance(node, _ast.Assign):
            targets, value = node.targets, node.value
